__rt_divzero_msg:
	.asciiz	"runtime error: division by zero\n"
	.text
# Called by the inline check before every `div' whose divisor is zero:
# message on stderr, exit status 70 (the same status as irsim).
__rt_divzero:
	li	$a0, 2
	la	$a1, __rt_divzero_msg
	li	$a2, 32
	li	$v0, 15
	syscall
	li	$a0, 70
	li	$v0, 17
	syscall

